export const getBagsLuggageProducts = (): Product[] => BAGS_LUGGAGE_PRODUCTS;

export const getFeaturedBagsLuggageProducts = (): Product[] => 
  BAGS_LUGGAGE_PRODUCTS.filter(product => product.featured);

export const getBagsLuggageProductsByBadge = (badge: string): Product[] =>
  BAGS_LUGGAGE_PRODUCTS.filter(product => product.badge === badge);

export const getBagsLuggageProductsByPriceRange = (min: number, max: number): Product[] =>
  BAGS_LUGGAGE_PRODUCTS.filter(product => product.price >= min && product.price <= max);
